def find_connected_components(grid, positions):
    """Find 4-connected components of positions"""
    visited = set()
    components = []

    def get_all_connected(pos, current_comp):
        h, w = len(grid), len(grid[0])
        queue = [pos]
        visited.add(pos)

        while queue:
            r, c = queue.pop(0)
            current_comp.add((r, c))
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) not in visited and grid[nr][nc] == 4:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

    for pos in positions:
        if pos not in visited:
            current_comp = set()
            get_all_connected(pos, current_comp)
            components.append(current_comp)

    return components

