def between_h(grid, r, c, fg_color):
    """Check if bg at (r,c) is directly between two fg cells horizontally"""
    h, w = len(grid), len(grid[0])
    # Look left and right
    for dc_h_left in range(1, c+1):
        if grid[r][c-dc_h_left] == fg_color:
            break
    else:  # no break means didn't find fg cell to left
        return None

    for dc_h_right in range(1, w-c):
        if grid[r][c+dc_h_right] == fg_color:
            break
    else:  # no break means didn't find fg cell to right
        return None

    return 'h'

def between_v(grid, r, c, fg_color):
    """Check if bg at (r,c) is directly between two fg cells vertically"""
    h, w = len(grid), len(grid[0])
    # Look up and down
    for dc_v_up in range(1, r+1):
        if grid[r-dc_v_up][c] == fg_color:
            break
    else:  # no break means didn't find fg cell above
        return None

    for dc_v_down in range(1, h-r):
        if grid[r+dc_v_down][c] == fg_color:
            break
    else:  # no break means didn't find fg cell below
        return None

    return 'v'

