def becomes_2(r, c, grid, fg_color=8, bg_color=3):
    if grid[r][c] != bg_color:
        return False

    # Check row
    has_fg_left = False
    has_fg_right = False
    for dc in range(1, c + 1):
        if grid[r][c - dc] == fg_color:
            has_fg_left = True
    for dc in range(1, len(grid[0]) - c):
        if grid[r][c + dc] == fg_color:
            has_fg_right = True

    # Check column
    if has_fg_left and has_fg_right:
        return True

    has_fg_up = False
    has_fg_down = False
    for dc in range(1, r + 1):
        if grid[r - dc][c] == fg_color:
            has_fg_up = True
    for dc in range(1, len(grid) - r):
        if grid[r + dc][c] == fg_color:
            has_fg_down = True

    if has_fg_up and has_fg_down:
        return True

    return False

